40	template <typename> class QuantileTiming;
41	
42	
43	/** Generic aggregate function for calculation of quantiles.
44	  * It depends on quantile calculation data structure. Look at Quantile*.h for various implementations.
45	  */
46	
47	template <
48	    /// Type of first argument.
49	    typename Value,
50	    /// Data structure and implementation of calculation. Look at QuantileExact.h for example.
51	    typename Data,
52	    /// Structure with static member "name", containing the name of the aggregate function.
53	    typename Name,
54	    /// If true, the function accepts the second argument
55	    /// (in can be "weight" to calculate quantiles or "determinator" that is used instead of PRNG).
56	    /// Second argument is always obtained through 'getUInt' method.
57	    bool has_second_arg,
58	    /// If non-void, the function will return float of specified type with possibly interpolated results and NaN if there was no values.
59	    /// Otherwise it will return Value type and default value if there was no values.
60	    /// As an example, the function cannot return floats, if the SQL type of argument is Date or DateTime.
61	    typename FloatReturnType,
62	    /// If true, the function will accept multiple parameters with quantile levels
63	    ///  and return an Array filled with many values of that quantiles.
64	    bool returns_many
65	>
66	class AggregateFunctionQuantile final : public IAggregateFunctionDataHelper<Data,
67	    AggregateFunctionQuantile<Value, Data, Name, has_second_arg, FloatReturnType, returns_many>>
68	{
69	private:
70	    using ColVecType = ColumnVectorOrDecimal<Value>;
71	
72	    static constexpr bool returns_float = !(std::is_same_v<FloatReturnType, void>);
73	    static_assert(!is_decimal<Value> || !returns_float);
74	
75	    QuantileLevels<Float64> levels;
76	
77	    /// Used when there are single level to get.
78	    Float64 level = 0.5;
79	
80	    DataTypePtr & argument_type;
81	
82	public:
83	    AggregateFunctionQuantile(const DataTypes & argument_types_, const Array & params)
84	        : IAggregateFunctionDataHelper<Data, AggregateFunctionQuantile<Value, Data, Name, has_second_arg, FloatReturnType, returns_many>>(argument_types_, params)
85	        , levels(params, returns_many), level(levels.levels[0]), argument_type(this->argument_types[0])
86	    {
87	        if (!returns_many && levels.size() > 1)
88	            throw Exception("Aggregate function " + getName() + " require one parameter or less", ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH);
89	    }
90	
91	    String getName() const override { return Name::name; }
92	
93	    DataTypePtr getReturnType() const override
94	    {
95	        DataTypePtr res;
96	
97	        if constexpr (returns_float)
98	            res = std::make_shared<DataTypeNumber<FloatReturnType>>();
99	        else
100	            res = argument_type;
101	
102	        if constexpr (returns_many)
103	            return std::make_shared<DataTypeArray>(res);
104	        else
105	            return res;
106	    }
107	
108	    bool haveSameStateRepresentation(const IAggregateFunction & rhs) const override
109	    {
110	        return getName() == rhs.getName() && this->haveEqualArgumentTypes(rhs);
111	    }
112	
113	    bool allocatesMemoryInArena() const override { return false; }
114	
115	    void add(AggregateDataPtr __restrict place, const IColumn ** columns, size_t row_num, Arena *) const override
116	    {
117	        auto value = static_cast<const ColVecType &>(*columns[0]).getData()[row_num];
118	
119	        if constexpr (std::is_same_v<Data, QuantileTiming<Value>>)
120	        {
121	            /// QuantileTiming only supports unsigned integers. Too large values are also meaningless.
122	            if (isNaN(value) || value > std::numeric_limits<Int64>::max() || value < 0)
123	                return;
124	        }
125	
126	        if constexpr (has_second_arg)
127	            this->data(place).add(
128	                value,
129	                columns[1]->getUInt(row_num));
130	        else
131	            this->data(place).add(value);
132	    }
133	
134	    void merge(AggregateDataPtr __restrict place, ConstAggregateDataPtr rhs, Arena *) const override
135	    {
136	        this->data(place).merge(this->data(rhs));
137	    }
138	
139	    void serialize(ConstAggregateDataPtr __restrict place, WriteBuffer & buf, std::optional<size_t> /* version */) const override
140	    {
141	        /// const_cast is required because some data structures apply finalizaton (like compactization) before serializing.
142	        this->data(const_cast<AggregateDataPtr>(place)).serialize(buf);
143	    }
144	
145	    void deserialize(AggregateDataPtr __restrict place, ReadBuffer & buf, std::optional<size_t> /* version */, Arena *) const override
146	    {
147	        this->data(place).deserialize(buf);
148	    }
149	
150	    void insertResultInto(AggregateDataPtr __restrict place, IColumn & to, Arena *) const override
151	    {
152	        /// const_cast is required because some data structures apply finalizaton (like sorting) for obtain a result.
153	        auto & data = this->data(place);
154	
155	        if constexpr (returns_many)
156	        {
157	            ColumnArray & arr_to = assert_cast<ColumnArray &>(to);
158	            ColumnArray::Offsets & offsets_to = arr_to.getOffsets();
159	
160	            size_t size = levels.size();
161	            offsets_to.push_back(offsets_to.back() + size);
162	
163	            if (!size)
164	                return;
165	
166	            if constexpr (returns_float)
167	            {
168	                auto & data_to = assert_cast<ColumnVector<FloatReturnType> &>(arr_to.getData()).getData();
169	                size_t old_size = data_to.size();
170	                data_to.resize(data_to.size() + size);
171	
172	                data.getManyFloat(levels.levels.data(), levels.permutation.data(), size, data_to.data() + old_size);
173	            }
174	            else
175	            {
176	                auto & data_to = static_cast<ColVecType &>(arr_to.getData()).getData();
177	                size_t old_size = data_to.size();
178	                data_to.resize(data_to.size() + size);
179	
180	                data.getMany(levels.levels.data(), levels.permutation.data(), size, data_to.data() + old_size);
181	            }
182	        }
183	        else
184	        {
185	            if constexpr (returns_float)
186	                assert_cast<ColumnVector<FloatReturnType> &>(to).getData().push_back(data.getFloat(level));
187	            else
188	                static_cast<ColVecType &>(to).getData().push_back(data.get(level));
189	        }
190	    }
191	
192	    static void assertSecondArg(const DataTypes & types)
193	    {
194	        if constexpr (has_second_arg)
195	        {
196	            assertBinary(Name::name, types);
197	            if (!isUnsignedInteger(types[1]))
198	                throw Exception("Second argument (weight) for function " + std::string(Name::name) + " must be unsigned integer, but it has type " + types[1]->getName(), ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
199	        }
200	        else
201	            assertUnary(Name::name, types);
202	    }
203	};
