173	    factory.registerFunction(NameQuantilesBFloat16Weighted::name, createAggregateFunctionQuantile<FuncQuantilesBFloat16Weighted>);
174	
175	    /// 'median' is an alias for 'quantile'
176	    factory.registerAlias("median", NameQuantile::name);
177	    factory.registerAlias("medianDeterministic", NameQuantileDeterministic::name);
