25	/*
26	 * hex(x) - Returns hexadecimal representation; capital letters; there are no prefixes 0x or suffixes h.
27	 *          For numbers, returns a variable-length string - hex in the "human" (big endian) format, with the leading zeros being cut,
28	 *          but only by whole bytes. For dates and datetimes - the same as for numbers.
29	 *          For example, hex(257) = '0101'.
30	 *
31	 * unhex(string) - Returns a string, hex of which is equal to `string` with regard of case and discarding one leading zero.
32	 *                 If such a string does not exist, could return arbitrary implementation specific value.
33	 *
34	 * bin(x) - Returns binary representation.
35	 *
36	 * unbin(x) - Returns a string, opposite to `bin`.
37	 *
38	 */
39	
40	struct HexImpl
41	{
42	    static constexpr auto name = "hex";
43	    static constexpr size_t word_size = 2;
44	
45	    template <typename T>
46	    static void executeOneUIntOrInt(T x, char *& out, bool skip_leading_zero = true, bool auto_close = true)
47	    {
48	        bool was_nonzero = false;
49	        for (int offset = (sizeof(T) - 1) * 8; offset >= 0; offset -= 8)
50	        {
51	            UInt8 byte = x >> offset;
52	
53	            /// Skip leading zeros
54	            if (byte == 0 && !was_nonzero && offset && skip_leading_zero) //-V560
55	                continue;
56	
57	            was_nonzero = true;
58	            writeHexByteUppercase(byte, out);
59	            out += word_size;
60	        }
61	        if (auto_close)
62	        {
63	            *out = '\0';
64	            ++out;
65	        }
66	    }
67	
68	    static void executeOneString(const UInt8 * pos, const UInt8 * end, char *& out)
69	    {
70	        while (pos < end)
71	        {
72	            writeHexByteUppercase(*pos, out);
73	            ++pos;
74	            out += word_size;
75	        }
76	        *out = '\0';
77	        ++out;
78	    }
79	
80	    template <typename T>
81	    static void executeFloatAndDecimal(const T & in_vec, ColumnPtr & col_res, const size_t type_size_in_bytes)
82	    {
83	        const size_t hex_length = type_size_in_bytes * word_size + 1; /// Including trailing zero byte.
84	        auto col_str = ColumnString::create();
85	
86	        ColumnString::Chars & out_vec = col_str->getChars();
87	        ColumnString::Offsets & out_offsets = col_str->getOffsets();
88	
89	        size_t size = in_vec.size();
90	        out_offsets.resize(size);
91	        out_vec.resize(size * hex_length);
92	
93	        size_t pos = 0;
94	        char * out = reinterpret_cast<char *>(out_vec.data());
95	        for (size_t i = 0; i < size; ++i)
96	        {
97	            const UInt8 * in_pos = reinterpret_cast<const UInt8 *>(&in_vec[i]);
98	            executeOneString(in_pos, in_pos + type_size_in_bytes, out);
99	
100	            pos += hex_length;
101	            out_offsets[i] = pos;
102	        }
103	        col_res = std::move(col_str);
104	    }
105	};
106	
107	struct UnhexImpl
108	{
109	    static constexpr auto name = "unhex";
110	    static constexpr size_t word_size = 2;
111	
112	    static void decode(const char * pos, const char * end, char *& out)
113	    {
114	        if ((end - pos) & 1)
115	        {
116	            *out = unhex(*pos);
117	            ++out;
118	            ++pos;
119	        }
120	        while (pos < end)
121	        {
122	            *out = unhex2(pos);
123	            pos += word_size;
124	            ++out;
125	        }
126	        *out = '\0';
127	        ++out;
128	    }
129	};
