198	struct UnbinImpl
199	{
200	    static constexpr auto name = "unbin";
201	    static constexpr size_t word_size = 8;
202	
203	    static void decode(const char * pos, const char * end, char *& out)
204	    {
205	        if (pos == end)
206	        {
207	            *out = '\0';
208	            ++out;
209	            return;
210	        }
211	
212	        UInt8 left = 0;
213	
214	        /// end - pos is the length of input.
215	        /// (length & 7) to make remain bits length mod 8 is zero to split.
216	        /// e.g. the length is 9 and the input is "101000001",
217	        /// first left_cnt is 1, left is 0, right shift, pos is 1, left = 1
218	        /// then, left_cnt is 0, remain input is '01000001'.
219	        for (UInt8 left_cnt = (end - pos) & 7; left_cnt > 0; --left_cnt)
220	        {
221	            left = left << 1;
222	            if (*pos != '0')
223	                left += 1;
224	            ++pos;
225	        }
226	
227	        if (left != 0 || end - pos == 0)
228	        {
229	            *out = left;
230	            ++out;
231	        }
232	
233	        assert((end - pos) % 8 == 0);
234	
235	        while (end - pos != 0)
236	        {
237	            UInt8 c = 0;
238	            for (UInt8 i = 0; i < 8; ++i)
239	            {
240	                c = c << 1;
241	                if (*pos != '0')
242	                    c += 1;
243	                ++pos;
244	            }
245	            *out = c;
246	            ++out;
247	        }
248	
249	        *out = '\0';
250	        ++out;
251	    }
252	};
