254	/// Encode number or string to string with binary or hexadecimal representation
255	template <typename Impl>
256	class EncodeToBinaryRepresentation : public IFunction
257	{
258	public:
259	    static constexpr auto name = Impl::name;
260	    static constexpr size_t word_size = Impl::word_size;
261	
262	    static FunctionPtr create(ContextPtr) { return std::make_shared<EncodeToBinaryRepresentation>(); }
263	
264	    String getName() const override { return name; }
265	
266	    size_t getNumberOfArguments() const override { return 1; }
267	
268	    bool useDefaultImplementationForConstants() const override { return true; }
269	
270	    bool isInjective(const ColumnsWithTypeAndName &) const override { return true; }
271	
272	    bool isSuitableForShortCircuitArgumentsExecution(const DataTypesWithConstInfo & /*arguments*/) const override { return false; }
273	
274	    DataTypePtr getReturnTypeImpl(const DataTypes & arguments) const override
275	    {
276	        WhichDataType which(arguments[0]);
277	
278	        if (!which.isStringOrFixedString() &&
279	            !which.isDate() &&
280	            !which.isDateTime() &&
281	            !which.isDateTime64() &&
282	            !which.isUInt() &&
283	            !which.isInt() &&
284	            !which.isFloat() &&
285	            !which.isDecimal() &&
286	            !which.isUUID() &&
287	            !which.isAggregateFunction())
288	            throw Exception("Illegal type " + arguments[0]->getName() + " of argument of function " + getName(),
289	                            ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
290	
291	        return std::make_shared<DataTypeString>();
292	    }
293	
294	    ColumnPtr executeImpl(const ColumnsWithTypeAndName & arguments, const DataTypePtr &, size_t /*input_rows_count*/) const override
295	    {
296	        const IColumn * column = arguments[0].column.get();
297	        ColumnPtr res_column;
298	
299	        WhichDataType which(column->getDataType());
300	        if (which.isAggregateFunction())
301	        {
302	            const ColumnPtr to_string = castColumn(arguments[0], std::make_shared<DataTypeString>());
303	            const auto * str_column = checkAndGetColumn<ColumnString>(to_string.get());
304	            tryExecuteString(str_column, res_column);
305	            return res_column;
306	        }
307	
308	        if (tryExecuteUIntOrInt<UInt8>(column, res_column) ||
309	            tryExecuteUIntOrInt<UInt16>(column, res_column) ||
310	            tryExecuteUIntOrInt<UInt32>(column, res_column) ||
311	            tryExecuteUIntOrInt<UInt64>(column, res_column) ||
312	            tryExecuteUIntOrInt<UInt128>(column, res_column) ||
313	            tryExecuteUIntOrInt<UInt256>(column, res_column) ||
314	            tryExecuteUIntOrInt<Int8>(column, res_column) ||
315	            tryExecuteUIntOrInt<Int16>(column, res_column) ||
316	            tryExecuteUIntOrInt<Int32>(column, res_column) ||
317	            tryExecuteUIntOrInt<Int64>(column, res_column) ||
318	            tryExecuteUIntOrInt<Int128>(column, res_column) ||
319	            tryExecuteUIntOrInt<Int256>(column, res_column) ||
320	            tryExecuteString(column, res_column) ||
321	            tryExecuteFixedString(column, res_column) ||
322	            tryExecuteFloat<Float32>(column, res_column) ||
323	            tryExecuteFloat<Float64>(column, res_column) ||
324	            tryExecuteDecimal<Decimal32>(column, res_column) ||
325	            tryExecuteDecimal<Decimal64>(column, res_column) ||
326	            tryExecuteDecimal<Decimal128>(column, res_column) ||
327	            tryExecuteUUID(column, res_column))
328	            return res_column;
329	
330	        throw Exception("Illegal column " + arguments[0].column->getName()
331	                        + " of argument of function " + getName(),
332	                        ErrorCodes::ILLEGAL_COLUMN);
333	    }
334	
335	    template <typename T>
336	    bool tryExecuteUIntOrInt(const IColumn * col, ColumnPtr & col_res) const
337	    {
338	        const ColumnVector<T> * col_vec = checkAndGetColumn<ColumnVector<T>>(col);
339	
340	        static constexpr size_t MAX_LENGTH = sizeof(T) * word_size + 1;    /// Including trailing zero byte.
341	
342	        if (col_vec)
343	        {
344	            auto col_str = ColumnString::create();
345	            ColumnString::Chars & out_vec = col_str->getChars();
346	            ColumnString::Offsets & out_offsets = col_str->getOffsets();
347	
348	            const typename ColumnVector<T>::Container & in_vec = col_vec->getData();
349	
350	            size_t size = in_vec.size();
351	            out_offsets.resize(size);
352	            out_vec.resize(size * (word_size+1) + MAX_LENGTH); /// word_size+1 is length of one byte in hex/bin plus zero byte.
353	
354	            size_t pos = 0;
355	            for (size_t i = 0; i < size; ++i)
356	            {
357	                /// Manual exponential growth, so as not to rely on the linear amortized work time of `resize` (no one guarantees it).
358	                if (pos + MAX_LENGTH > out_vec.size())
359	                    out_vec.resize(out_vec.size() * word_size + MAX_LENGTH);
360	
361	                char * begin = reinterpret_cast<char *>(&out_vec[pos]);
362	                char * end = begin;
363	                Impl::executeOneUIntOrInt(in_vec[i], end);
364	
365	                pos += end - begin;
366	                out_offsets[i] = pos;
367	            }
368	            out_vec.resize(pos);
369	
370	            col_res = std::move(col_str);
371	            return true;
372	        }
373	        else
374	        {
375	            return false;
376	        }
377	    }
378	
379	    bool tryExecuteString(const IColumn *col, ColumnPtr &col_res) const
380	    {
381	        const ColumnString * col_str_in = checkAndGetColumn<ColumnString>(col);
382	
383	        if (col_str_in)
384	        {
385	            auto col_str = ColumnString::create();
386	            ColumnString::Chars & out_vec = col_str->getChars();
387	            ColumnString::Offsets & out_offsets = col_str->getOffsets();
388	
389	            const ColumnString::Chars & in_vec = col_str_in->getChars();
390	            const ColumnString::Offsets & in_offsets = col_str_in->getOffsets();
391	
392	            size_t size = in_offsets.size();
393	
394	            out_offsets.resize(size);
395	            /// reserve `word_size` bytes for each non trailing zero byte from input + `size` bytes for trailing zeros
396	            out_vec.resize((in_vec.size() - size) * word_size + size);
397	
398	            char * begin = reinterpret_cast<char *>(out_vec.data());
399	            char * pos = begin;
400	            size_t prev_offset = 0;
401	
402	            for (size_t i = 0; i < size; ++i)
403	            {
404	                size_t new_offset = in_offsets[i];
405	
406	                Impl::executeOneString(&in_vec[prev_offset], &in_vec[new_offset - 1], pos);
407	
408	                out_offsets[i] = pos - begin;
409	
410	                prev_offset = new_offset;
411	            }
412	            if (!out_offsets.empty() && out_offsets.back() != out_vec.size())
413	                throw Exception("Column size mismatch (internal logical error)", ErrorCodes::LOGICAL_ERROR);
414	
415	            col_res = std::move(col_str);
416	            return true;
417	        }
418	        else
419	        {
420	            return false;
421	        }
422	    }
423	
424	    template <typename T>
425	    bool tryExecuteDecimal(const IColumn * col, ColumnPtr & col_res) const
426	    {
427	        const ColumnDecimal<T> * col_dec = checkAndGetColumn<ColumnDecimal<T>>(col);
428	        if (col_dec)
429	        {
430	            const typename ColumnDecimal<T>::Container & in_vec = col_dec->getData();
431	            Impl::executeFloatAndDecimal(in_vec, col_res, sizeof(T));
432	            return true;
