512	            ColumnString::Offsets & out_offsets = col_str->getOffsets();
513	
514	            const typename ColumnUUID::Container & in_vec = col_vec->getData();
515	            const UUID* uuid = in_vec.data();
516	
517	            size_t size = in_vec.size();
518	            out_offsets.resize(size);
519	            out_vec.resize(size * (word_size+1) + MAX_LENGTH); /// word_size+1 is length of one byte in hex/bin plus zero byte.
520	
521	            size_t pos = 0;
522	            for (size_t i = 0; i < size; ++i)
523	            {
524	                /// Manual exponential growth, so as not to rely on the linear amortized work time of `resize` (no one guarantees it).
525	                if (pos + MAX_LENGTH > out_vec.size())
526	                    out_vec.resize(out_vec.size() * word_size + MAX_LENGTH);
527	
528	                char * begin = reinterpret_cast<char *>(&out_vec[pos]);
529	                char * end = begin;
530	
531	                // use executeOnUInt instead of using executeOneString
