534	                Impl::executeOneUIntOrInt(uuid[i].toUnderType().items[1], end, false, true);
535	
536	                pos += end - begin;
537	                out_offsets[i] = pos;
538	            }
539	            out_vec.resize(pos);
540	
541	            col_res = std::move(col_str);
