#pragma once

#include <Analyzer/IQueryTreePass.h>

namespace DB
{

/** Eliminate injective functions in the argument list of `uniq`-style aggregate functions.
  *
  * Injective functions do not change the number of distinct values,
  * so wrapping an argument of `uniq`, `uniqExact`, `uniqHLL12`, `uniqTheta`, `uniqCombined`, `uniqCombined64`
  * in an injective function does not affect the result and can be removed before execution.
  *
  * Example: SELECT uniq(f(x)) is rewritten into SELECT uniq(x) if f is injective.
  */
class UniqInjectiveFunctionsEliminationPass final : public IQueryTreePass
{
public:
    String getName() override { return "UniqInjectiveFunctionsEliminationPass"; }

    String getDescription() override
    {
        return "Eliminate injective functions in the argument list of uniq* functions";
    }

    void run(QueryTreeNodePtr query_tree_node, ContextPtr context) override;
};

}

#include <Analyzer/Passes/UniqInjectiveFunctionsEliminationPass.h>

#include <Functions/FunctionFactory.h>

#include <Analyzer/InDepthQueryTreeVisitor.h>
#include <Analyzer/FunctionNode.h>

#include <Interpreters/Context.h>

namespace DB
{

namespace
{

/// `uniq`-style aggregate functions return the number of distinct argument values,
/// therefore injective functions applied to their arguments can be eliminated.
static const std::unordered_set<String> uniq_functions_names
    = {"uniq", "uniqExact", "uniqHLL12", "uniqTheta", "uniqCombined", "uniqCombined64"};

class UniqInjectiveFunctionsEliminationVisitor : public InDepthQueryTreeVisitor<UniqInjectiveFunctionsEliminationVisitor>
{
public:
    explicit UniqInjectiveFunctionsEliminationVisitor(ContextPtr context_)
        : context(context_)
    {}

    void enterImpl(QueryTreeNodePtr & node)
    {
        auto * function_node = node->as<FunctionNode>();
        if (!function_node || !function_node->isAggregateFunction())
            return;

        if (!uniq_functions_names.contains(function_node->getFunctionName()))
            return;

        for (auto & argument : function_node->getArguments().getNodes())
        {
            auto * argument_function_node = argument->as<FunctionNode>();
            if (!argument_function_node || !argument_function_node->isOrdinaryFunction())
                continue;

            auto function = FunctionFactory::instance().tryGet(argument_function_node->getFunctionName(), context);
            if (!function || !function->isInjective({}))
                continue;

            auto & inner_arguments = argument_function_node->getArguments().getNodes();
            if (inner_arguments.size() != 1)
                continue;

            /// Replace `uniq(f(x))` with `uniq(x)` for injective `f`
            argument = inner_arguments[0];
        }
    }

private:
    ContextPtr context;
};

}

void UniqInjectiveFunctionsEliminationPass::run(QueryTreeNodePtr query_tree_node, ContextPtr context)
{
    UniqInjectiveFunctionsEliminationVisitor visitor(context);
    visitor.visit(query_tree_node);
}

}

